# build_fig215_v3.R — Figure 2.15 REBUILT on the v3 corrected series
#
# Follows the Fig 2.13 / original 2.14 conventions: lettered panels, short noun-phrase
# titles, descriptive subtitles carrying NO results, greyscale, theme_minimal(base_size=10),
# a break-test panel. Statistics stay OFF the panels and go to FIG215_FOOTNOTE_NOTES.md,
# generated by this script so they cannot drift.
#
# SERIES (PJ's decision, 10 Aug 2026): the COUNT measure on the SUFFICIENT-extract series.
# Implemented as (serious rate among sufficient extracts) x (all VFM reports that year).
#   Why not the raw count within the sufficient subset: sufficiency coverage TRENDS UPWARD
#   (+0.31 pts/yr, p=0.006; 70% pre-1997 -> 79% later), so a raw count would carry a built-in
#   ~13% artefactual rise. The rate-times-full-volume form uses the better rate estimate and
#   the true denominator. It correlates 0.989 with the raw count.
#
# PUBLICATION VOLUME IS NO LONGER A PANEL (PJ, 10 Aug 2026). It is the live confound - the rise
# in serious findings coincides with a fall in reports published - and it used to be panel B.
# It now lives in the additional-tables appendix, covering all 42 years, and the footnote cites
# it. See build_nao_output_table.R.
#
#   Rscript data_workspace_2026-07/nao_extension/diagnostics/build_fig215_v3.R

suppressPackageStartupMessages({
  library(dplyr); library(ggplot2); library(patchwork)
})

ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), "../../..")) else getwd()
})
setwd(ROOT)
source("data_workspace_2026-07/chow_standardized/chow_test.R")
WS  <- "data_workspace_2026-07/nao_extension"
OUT <- file.path(WS, "diagnostics")
set.seed(42)

CV <- read.csv(file.path(WS, "diagnostics/fig213_computed_values.csv"), stringsAsFactors = FALSE)
V <- function(k) { i <- match(k, CV$key)
                   if (is.na(i)) stop("no computed value for '", k, "' - run fig213_supporting_tests.R")
                   CV$value[i] }

d <- read.csv(file.path(WS, "pdf_era/nao_final.csv")) |> arrange(year) |>
  mutate(serious = est_count)

# THE 1997-98 GAP IS CLOSED (10 Aug 2026). All 69 missing reports were recovered as ORIGINAL
# NAO PDFs from the UK Government Web Archive - the URL needs `id_` after the timestamp AND the
# 2017 capture rather than the 2022 one the NAO's own pages link to. 1997 now has 40 coded VFM
# reports (21 verdict-bearing), 1998 has 39 (23), so both clear the 15/10 thresholds on the
# same instrument as every other year. The gap rows and dotted bridge that used to sit here
# have been REMOVED: leaving them would have plotted NA rows over real data and drawn a break
# in a series that no longer has one.
# THE LINE MUST BREAK WHERE THERE IS NO ESTIMATE (PJ, 10 Aug 2026: "that is deceptive").
# 1987, 1988 and 1999 carry no rate estimate - too few of their reports state an explicit
# verdict - so explicit NA rows are inserted and geom_line breaks. No bridge, dotted or
# otherwise: nothing is interpolated, and the reader should see that. The reports themselves
# exist and are shown in the additional-tables appendix figure, which plots published counts
# alongside serious findings for all 42 years.
cnt <- read.csv(file.path(WS, "pdf_era/nao_counts.csv"))
absent_yrs <- setdiff(min(d$year):max(d$year), d$year)

d_plot <- merge(data.frame(year = min(d$year):max(d$year)), d, by = "year", all.x = TRUE)

# Era boundaries updated: the second era ran "1999-2004" only because 1997-98 were missing.
# With both years restored it is 1997-2004.
eras <- d |>
  mutate(e = case_when(year <= 1996 ~ "1984-96", year <= 2004 ~ "1997-2004",
                       year <= 2013 ~ "2005-13", TRUE ~ "2014-25")) |>
  group_by(e) |>
  summarise(serious = mean(serious), reports = mean(n_all), .groups = "drop") |>
  mutate(x1 = c(1984, 1997, 2005, 2014), x2 = c(1996, 2004, 2013, 2025))

# Supporting tests (leave-one-out, Bai-Perron, the Poisson volume control) live in
# diagnostics/fig213_supporting_tests.R and were re-run on the completed 39-year series on
# 10 Aug 2026. Their results are quoted below; re-run that script if the series changes.

chow <- chow_sweep(year = d$year, y = d$serious)

base_thm <- theme_minimal(base_size = 10) +
  theme(panel.grid.minor = element_blank(),
# 17 Aug, PJ: "some of the titles are too small typface". Title size was a raw pt value while
# canvases run 6.5-10 in, so the SAME pt looked large on a narrow figure and small on a wide
# one - a 68% spread in apparent size. Titles are now set at ~1.75 pt per inch of canvas
# (this figure is 7.6 in wide, so 13.5 pt), which is the ratio the narrow figures already had.
        plot.title    = element_text(face = "bold", size = 10),
        plot.subtitle = element_text(size = 8, colour = "grey30"))

pA <- ggplot(d_plot, aes(year, serious)) +
  # POINTS + LOESS, not a connected line (PJ, 10 Aug 2026). A line has to do something at
  # 1987, 1988 and 1999, where there is no estimate: joining across them interpolates values
  # that do not exist, and breaking it leaves three gaps that read as absent reports. Points
  # state exactly what is known year by year, and the smoother carries the shape without
  # asserting anything about the missing years. The smoother is DISPLAY ONLY - every statistic
  # on this figure, including the break test in panel B, is computed on the raw annual series.
  geom_smooth(method = "loess", formula = y ~ x, span = .6, se = TRUE,
              colour = "grey35", fill = "grey85", linewidth = .6) +
  geom_point(colour = "grey10", size = 1.5) +
  # counts must sit on a zero baseline: a truncated axis exaggerates the rise
  scale_y_continuous(limits = c(0, NA), expand = expansion(mult = c(0, .05))) +
  scale_x_continuous(breaks = seq(1985, 2025, 5), minor_breaks = seq(1984, 2025, 1)) +
  labs(x = NULL, y = "Reports coded serious failure",
       title = "Serious delivery failures identified per year",
       # COMPUTED, never typed. A hardcoded version of this line survived the OCR work and
       # printed "No estimate for 1987, 1988 or 1999" on a figure that plots 1987 and 1988.
       subtitle = paste0("National Audit Office value-for-money reports, 1984-2025. Points are ",
                         "annual estimates; the curve is a\nloess smoother with its 95 per cent ",
                         "interval. ",
                         if (length(absent_yrs) == 0) "Every year estimated."
                         else paste0("No estimate for ",
                                     paste(absent_yrs, collapse = ", "), "."))) +
  base_thm

# PANEL B (NAO output) MOVED OUT 10 Aug 2026 (PJ). It is now Table 2.x of the additional-tables
# appendix, generated by diagnostics/build_nao_output_table.R and referenced from the footnote
# notes below. Two reasons: it simplifies the figure, and the panel was defective - it drew on
# nao_final.csv, which drops years too few of whose reports carry an explicit verdict (1987,
# 1988, 1999), so it showed gaps in NAO OUTPUT for three years in which the Office published 28,
# 27 and 19 value-for-money reports. The table uses nao_counts.csv and covers all 42 years.

# Period-means panel dropped 10 Aug (PJ): the era boundaries are analytically arbitrary and a
# panel of them invites the reader to treat them as findings. Period means survive in the
# footnote notes, where they are described as a summary rather than shown as structure.

# chow_sweep returns `curve` already as a data.frame of k / year / F over the trimmed interior
sw <- chow$curve
pD <- ggplot(sw, aes(year, F)) +
  geom_hline(yintercept = chow$crit_5pct, linetype = "dashed",
             colour = "grey55", linewidth = .4) +
  geom_line(colour = "grey15", linewidth = .6) +
  geom_point(data = subset(sw, year == chow$peak_year),
             shape = 21, fill = "white", colour = "grey10", size = 2.4, stroke = .9) +
  scale_x_continuous(breaks = seq(1990, 2020, 5), minor_breaks = seq(1988, 2022, 1)) +
  labs(x = NULL, y = sprintf("Chow F(2,%d)", chow$n - 4),
       title = "B. Structural break test",
       subtitle = "Regression-based Chow F swept across candidate break years, intercept and slope both free to break; dashed line marks the 5% critical value.") +
  base_thm

fig <- pA +
  plot_annotation(
    title = "Figure 2.13: Serious delivery failures identified by the National Audit Office, 1984–2025",
    theme = theme(plot.title = element_text(face = "bold", size = 13.5,
                                            margin = margin(b = 10))))
ggsave("figures/fig_2_13_nao_delivery_failure_1984_2025.png", fig,
       width = 7.6, height = 3.9, dpi = 300, bg = "white")

